const puzzles=[{letters:['A','B','C','K','O','R','T'],center:'A',answers:['aback','abator','abort','abactor','actor','acrobat','arbor','art','bract','back','bar','barb','bark','boat','boa','boar','brat','cart','coat','cork','rack','rock','tab','tabor','track','trace','tar','tract','cobra','cobra']},{letters:['A','E','G','I','L','N','T'],center:'E',answers:['agile','angle','tangle','tangle','eagle','elegant','agent','alien','align','elating','gent','gentle','glean','glee','late','lean','lent','line','meal','meat','night','tale','teal','tile','tine']},{letters:['C','D','I','L','O','R','Y'],center:'O',answers:['cold','color','cord','corn','dollar','idol','lord','odor','old','or','oral','rory','radio','road','roil','roll','solid','sour','yodel']}];
